use op_state_store::{FieldSchema, FieldType, MethodDecl, PluginSchema, SideEffect};
use simd_json::{json, OwnedValue as Value};

/// Materialize a deterministic initial live state from a plugin schema.
///
/// This is the schema-side bootstrap for D-Bus projection creation. It never
/// queries a plugin backend and never invents data outside the contract:
/// field defaults win, then examples, then an empty value matching the field
/// type. The MutationEngine writes this once when no projection exists yet;
/// later mutations replace it through the normal `/dev/shm/opdbus/projections`
/// write door.
pub(crate) fn materialize_state_from_schema(schema: &PluginSchema) -> Value {
    if let Some(example) = &schema.example {
        return example.clone();
    }

    let mut state = simd_json::value::owned::Object::new();
    let mut fields = schema.fields.iter().collect::<Vec<_>>();
    fields.sort_by(|(a, _), (b, _)| a.cmp(b));

    for (name, field) in fields {
        state.insert(name.clone(), materialize_field(field));
    }

    Value::Object(Box::new(state))
}

fn materialize_field(field: &FieldSchema) -> Value {
    if let Some(value) = &field.default {
        return value.clone();
    }
    if let Some(value) = &field.example {
        return value.clone();
    }

    materialize_field_type(&field.field_type)
}

fn materialize_field_type(field_type: &FieldType) -> Value {
    match field_type {
        FieldType::String => json!(""),
        FieldType::Integer => json!(0),
        FieldType::Float => json!(0.0),
        FieldType::Boolean => json!(false),
        FieldType::Array(_) => json!([]),
        FieldType::Object(fields) => {
            let mut object = simd_json::value::owned::Object::new();
            let mut fields = fields.iter().collect::<Vec<_>>();
            fields.sort_by(|(a, _), (b, _)| a.cmp(b));
            for (name, field) in fields {
                object.insert(name.clone(), materialize_field(field));
            }
            Value::Object(Box::new(object))
        }
        FieldType::Enum(values) => values
            .first()
            .map(|value| json!(value))
            .unwrap_or_else(|| json!(null)),
        FieldType::OneOf(types) => types
            .first()
            .map(materialize_field_type)
            .unwrap_or_else(|| json!(null)),
        FieldType::Any => json!(null),
    }
}

/// Format a plugin's live state into a `PluginSchema`.
///
/// This is a *formatter*, not a schema authority — nothing here is indexed. The
/// plugin's live state (its `*State` struct) is the single source
/// of truth; field types are inferred from that state, so the schema can never
/// drift from what the plugin actually reports. To add a field, add it to the
/// plugin state — never hand-write a field definition.
pub(crate) fn schema_from_state(
    name: &str,
    category: &str,
    version: &str,
    description: &str,
    state: &Value,
) -> PluginSchema {
    use simd_json::prelude::*;

    let mut builder = PluginSchema::builder(name)
        .version(version)
        .category(category)
        .description(description);

    if let Some(obj) = state.as_object() {
        for (key, value) in obj.iter() {
            builder = builder.field(&key.to_string(), field_from_value(value));
        }
    }

    builder.example(state.clone()).build()
}

/// Infer a `FieldSchema` (type + example) from a live state value.
pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
    FieldSchema {
        field_type: infer_field_type(value),
        required: false,
        description: String::new(),
        default: None,
        example: Some(value.clone()),
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
pub(crate) fn infer_field_type(value: &Value) -> FieldType {
    use simd_json::prelude::*;

    if value.is_null() {
        FieldType::Any
    } else if value.as_bool().is_some() {
        FieldType::Boolean
    } else if value.as_i64().is_some() || value.as_u64().is_some() {
        FieldType::Integer
    } else if value.as_f64().is_some() {
        FieldType::Float
    } else if value.as_str().is_some() {
        FieldType::String
    } else if let Some(arr) = value.as_array() {
        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
        FieldType::Array(Box::new(inner))
    } else if let Some(obj) = value.as_object() {
        let fields = obj
            .iter()
            .map(|(k, v)| (k.to_string(), field_from_value(v)))
            .collect();
        FieldType::Object(fields)
    } else {
        FieldType::Any
    }
}

pub(crate) fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
    FieldSchema {
        field_type: FieldType::Any,
        required,
        description: description.to_string(),
        default,
        example: None,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

pub(crate) fn cap_method(
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    required_capability: &str,
    subid: &str,
) -> MethodDecl {
    MethodDecl {
        name: name.to_string(),
        args: json!({"type": "object", "additionalProperties": true}),
        returns: Some(json!({"type": "object", "additionalProperties": true})),
        side_effect,
        idempotent,
        required_capability: Some(required_capability.to_string()),
        subid: subid.to_string(),
    }
}

/// Create a MethodDecl from a schemars-typed input struct.
///
/// This is the canonical pattern for all plugins: define method inputs as
/// Rust structs with `#[derive(schemars::JsonSchema)]`, then use this function
/// to generate typed method declarations. The resulting schema drives D-Bus method
/// validation and gRPC proto generation.
pub fn method_decl_from_schemars<Input: schemars::JsonSchema>(
    name: &str,
    side_effect: SideEffect,
    idempotent: bool,
    required_capability: &str,
    subid: &str,
) -> MethodDecl {
    let serde_schema = serde_json::to_value(schemars::schema_for!(Input)).unwrap();
    let schema_bytes = serde_json::to_vec(&serde_schema).unwrap();
    let mut schema_bytes = schema_bytes;
    let args = simd_json::to_owned_value(&mut schema_bytes).unwrap();
    MethodDecl {
        name: name.to_string(),
        args,
        returns: Some(json!({"type": "object"})),
        side_effect,
        idempotent,
        required_capability: Some(required_capability.to_string()),
        subid: subid.to_string(),
    }
}

pub(crate) fn simple_schema(
    name: &str,
    description: &str,
    dependencies: &[&str],
    fields: Vec<(&str, FieldSchema)>,
) -> PluginSchema {
    let mut builder = PluginSchema::builder(name)
        .version("1.0.0")
        .description(description);
    for dep in dependencies {
        builder = builder.dependency(dep);
    }
    for (field_name, schema) in fields {
        builder = builder.field(field_name, schema);
    }
    builder.build()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn field(field_type: FieldType, default: Option<Value>, example: Option<Value>) -> FieldSchema {
        FieldSchema {
            field_type,
            required: false,
            description: String::new(),
            default,
            example,
            constraints: Vec::new(),
            read_only: false,
            read_only_when: None,
        }
    }

    #[test]
    fn materializes_seed_state_from_schema_defaults_examples_and_types() {
        let schema = PluginSchema::builder("example")
            .field(
                "enabled",
                field(FieldType::Boolean, Some(json!(true)), Some(json!(false))),
            )
            .field("label", field(FieldType::String, None, Some(json!("demo"))))
            .field(
                "mode",
                field(
                    FieldType::Enum(vec!["active".to_string(), "passive".to_string()]),
                    None,
                    None,
                ),
            )
            .field(
                "choice",
                field(
                    FieldType::OneOf(vec![FieldType::Integer, FieldType::String]),
                    None,
                    None,
                ),
            )
            .field(
                "nested",
                field(
                    FieldType::Object(HashMap::from([(
                        "count".to_string(),
                        field(FieldType::Integer, None, None),
                    )])),
                    None,
                    None,
                ),
            )
            .build();

        let state = materialize_state_from_schema(&schema);

        assert_eq!(state["enabled"], json!(true));
        assert_eq!(state["label"], json!("demo"));
        assert_eq!(state["mode"], json!("active"));
        assert_eq!(state["choice"], json!(0));
        assert_eq!(state["nested"]["count"], json!(0));
    }
}

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::OwnedValue as Value;

/// ADC plugin state schema.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.adc.schema@v1"))]
pub struct AdcState {
    /// Whether ADC is configured.
    #[schemars(
        description = "Whether ADC is configured",
        extend("x-oscal-subid" = "exp.software.plugin.adc.configured.render@v1")
    )]
    pub configured: bool,
}

pub struct AdcPlugin;

impl Default for AdcPlugin {
    fn default() -> Self {
        Self
    }
}

impl AdcPlugin {
    pub fn new() -> Self {
        Self
    }
}

#[async_trait]
impl StatePlugin for AdcPlugin {
    fn name(&self) -> &str {
        "adc"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(adc_schema())
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "unknown".to_string(),
                desired_hash: "unknown".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: Value::null(),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Canonical `adc` schema, derived from the structs via schemars.
pub fn adc_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(AdcState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "adc",
        "1.0.0",
        "Application default credentials state",
        &root,
    )
}

/// Frozen golden reference: the original hand-rolled schema, kept test-only so
/// `derived_schema_matches_hand_rolled` can prove the derived schema still
/// matches the contract this plugin shipped with.
#[cfg(test)]
pub(crate) fn adc_schema_golden() -> PluginSchema {
    PluginSchema::builder("adc")
        .version("1.0.0")
        .description("Application default credentials state")
        .subid("__schema__", "sch.software.plugin.adc.schema@v1")
        .field(
            "configured",
            FieldSchema {
                field_type: FieldType::Boolean,
                required: true,
                description: "Whether ADC is configured".to_string(),
                default: None,
                example: None,
                constraints: Vec::new(),
                read_only: false,
                read_only_when: None,
            },
        )
        .subid("configured", "exp.software.plugin.adc.configured.render@v1")
        .build()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::state_plugins::common::oscal::validate_subid;

    #[test]
    fn derived_schema_matches_hand_rolled() {
        let golden = adc_schema_golden();
        let derived = adc_schema();
        let diffs = super::super::schemars_adapter::schema_diffs(&golden, &derived);
        assert!(diffs.is_empty(), "schema_diffs: {:#?}", diffs);
    }

    #[test]
    fn all_subids_are_valid() {
        let raw = serde_json::to_value(schemars::schema_for!(AdcState)).unwrap();
        let mut stack = vec![&raw];
        while let Some(node) = stack.pop() {
            if let Some(subid) = node.get("x-oscal-subid").and_then(|v| v.as_str()) {
                validate_subid(subid).expect("invalid subid");
            }
            if let Some(props) = node.get("properties").and_then(|v| v.as_object()) {
                for (_, v) in props {
                    stack.push(v);
                }
            }
            if let Some(defs) = node
                .get("$defs")
                .or_else(|| node.get("definitions"))
                .and_then(|v| v.as_object())
            {
                for (_, v) in defs {
                    stack.push(v);
                }
            }
        }
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("adc", |_ctx| std::sync::Arc::new(AdcPlugin::new()))
}

//! Systemd state plugin - manages systemd via org.freedesktop.systemd1 D-Bus
//! Maps D-Bus object tree to declarative state

use anyhow::{Context, Result};
use async_trait::async_trait;
use op_state::plugtree::PlugTree;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};
use simd_json::prelude::*;
use std::collections::HashMap;
use zbus::{Connection, Proxy};

/// Systemd configuration schema - mirrors D-Bus object tree
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SystemdConfig {
    /// Units indexed by name (e.g., "ssh.service")
    #[serde(skip_serializing_if = "Option::is_none")]
    pub units: Option<HashMap<String, UnitConfig>>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct UnitConfig {
    /// Desired state: "active", "inactive", "failed", etc.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub active_state: Option<String>,

    /// Should unit be enabled at boot
    #[serde(skip_serializing_if = "Option::is_none")]
    pub enabled: Option<bool>,

    /// Should unit be masked (prevents starting)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub masked: Option<bool>,

    /// Additional D-Bus properties (dynamic)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub properties: Option<HashMap<String, Value>>,
}

/// Systemd state plugin
pub struct SystemdStatePlugin;

impl SystemdStatePlugin {
    pub fn new() -> Self {
        Self
    }

    /// Connect to systemd via D-Bus
    async fn connect_systemd(&self) -> Result<Proxy<'static>> {
        let conn = Connection::system()
            .await
            .context("Failed to connect to system D-Bus")?;

        Proxy::new(
            &conn,
            "org.freedesktop.systemd1",
            "/org/freedesktop/systemd1",
            "org.freedesktop.systemd1.Manager",
        )
        .await
        .context("Failed to create systemd D-Bus proxy")
    }

    /// Get unit object path from unit name
    async fn get_unit_path(&self, proxy: &Proxy<'_>, unit_name: &str) -> Result<String> {
        let path: zbus::zvariant::OwnedObjectPath = proxy
            .call("GetUnit", &(unit_name,))
            .await
            .context(format!("Failed to get unit path for {}", unit_name))?;

        Ok(path.to_string())
    }

    /// Query current state of a unit
    async fn query_unit(&self, unit_name: &str) -> Result<UnitConfig> {
        let proxy = self.connect_systemd().await?;
        let unit_path = self.get_unit_path(&proxy, unit_name).await?;

        let conn = Connection::system().await?;
        let unit_proxy = Proxy::new(
            &conn,
            "org.freedesktop.systemd1",
            unit_path,
            "org.freedesktop.systemd1.Unit",
        )
        .await?;

        // Get ActiveState property
        let active_state: String = unit_proxy
            .get_property("ActiveState")
            .await
            .unwrap_or_else(|_| "unknown".to_string());

        // Check if enabled (this is a UnitFile property)
        let enabled = self.check_unit_enabled(&proxy, unit_name).await.ok();

        Ok(UnitConfig {
            active_state: Some(active_state),
            enabled,
            masked: None, // TODO: Query mask state
            properties: None,
        })
    }

    /// Check if unit is enabled
    async fn check_unit_enabled(&self, proxy: &Proxy<'_>, unit_name: &str) -> Result<bool> {
        let state: String = proxy
            .call("GetUnitFileState", &(unit_name,))
            .await
            .context("Failed to get unit file state")?;

        Ok(state == "enabled")
    }

    /// Start a systemd unit
    async fn start_unit(&self, unit_name: &str) -> Result<()> {
        let proxy = self.connect_systemd().await?;

        let _job: zbus::zvariant::OwnedObjectPath = proxy
            .call("StartUnit", &(unit_name, "replace"))
            .await
            .context(format!("Failed to start unit {}", unit_name))?;

        log::info!("Started systemd unit: {}", unit_name);
        Ok(())
    }

    /// Stop a systemd unit
    async fn stop_unit(&self, unit_name: &str) -> Result<()> {
        let proxy = self.connect_systemd().await?;

        let _job: zbus::zvariant::OwnedObjectPath = proxy
            .call("StopUnit", &(unit_name, "replace"))
            .await
            .context(format!("Failed to stop unit {}", unit_name))?;

        log::info!("Stopped systemd unit: {}", unit_name);
        Ok(())
    }

    /// Enable a systemd unit
    async fn enable_unit(&self, unit_name: &str) -> Result<()> {
        let proxy = self.connect_systemd().await?;

        let _: (bool, Vec<(String, String, String)>) = proxy
            .call("EnableUnitFiles", &(vec![unit_name], false, true))
            .await
            .context(format!("Failed to enable unit {}", unit_name))?;

        log::info!("Enabled systemd unit: {}", unit_name);
        Ok(())
    }

    /// Disable a systemd unit
    async fn disable_unit(&self, unit_name: &str) -> Result<()> {
        let proxy = self.connect_systemd().await?;

        let _: Vec<(String, String, String)> = proxy
            .call("DisableUnitFiles", &(vec![unit_name], false))
            .await
            .context(format!("Failed to disable unit {}", unit_name))?;

        log::info!("Disabled systemd unit: {}", unit_name);
        Ok(())
    }

    /// Apply desired unit configuration
    async fn apply_unit_config(&self, unit_name: &str, config: &UnitConfig) -> Result<()> {
        // Apply masked state first (prevents other operations)
        if let Some(desired_masked) = config.masked {
            // Check current mask state via GetUnitFileState
            let proxy = self.connect_systemd().await?;
            let state: String = proxy
                .call("GetUnitFileState", &(unit_name,))
                .await
                .unwrap_or_else(|_| "unknown".to_string());

            let currently_masked = state == "masked";

            if desired_masked && !currently_masked {
                self.mask_unit(unit_name).await?;
            } else if !desired_masked && currently_masked {
                self.unmask_unit(unit_name).await?;
            }
        }

        // Apply active state
        if let Some(ref desired_state) = config.active_state {
            let current = self.query_unit(unit_name).await?;
            let current_state = current
                .active_state
                .unwrap_or_else(|| "unknown".to_string());

            if desired_state == "active" && current_state != "active" {
                self.start_unit(unit_name).await?;
            } else if desired_state == "inactive" && current_state == "active" {
                self.stop_unit(unit_name).await?;
            }
        }

        // Apply enabled state
        if let Some(desired_enabled) = config.enabled {
            let current = self.query_unit(unit_name).await?;
            let current_enabled = current.enabled.unwrap_or(false);

            if desired_enabled && !current_enabled {
                self.enable_unit(unit_name).await?;
            } else if !desired_enabled && current_enabled {
                self.disable_unit(unit_name).await?;
            }
        }

        Ok(())
    }
}

